import openpyxl,re
wb=openpyxl.load_workbook('extraction/stec.xlsx')
dl,qs,df=wb['Deal ledger'],wb['Questions'],wb['Deal facts']
hdr=[c.value for c in dl[1]]; fi=hdr.index('Flag')
flags={r[0].value:(r[fi].value or '') for r in dl.iter_rows(min_row=2)}
qh=[c.value for c in qs[1]]
fields=['Question','Recommended answer','Why, with page','Rows affected','What changes if answered differently']
ok=True
def expand(s):
    out=[]
    for tok in s.replace('#','').split(','):
        tok=tok.strip()
        if '-' in tok:
            a,b=tok.split('-'); out+=list(range(int(a),int(b)+1))
        elif tok: out.append(int(tok))
    return out
for r in qs.iter_rows(min_row=2,values_only=True):
    d=dict(zip(qh,r)); q=d['Q']
    n=sum(len((d[f] or '').split()) for f in fields)
    print(q,'words=',n, 'rows=',d['Rows affected'])
    if n>70: ok=False; print('  TOO LONG')
    for x in expand(d['Rows affected']):
        if q not in flags.get(x,''):
            ok=False; print('  MISSING FLAG',q,'on #',x, repr(flags.get(x)))
print('Deal facts Number of processes =',repr(df.cell(11,2).value))
print('flags now:',{k:v for k,v in flags.items() if v})
print('formatting:',[(w.title,w.freeze_panes,w.auto_filter.ref) for w in wb])
print('ALL CERTAIN FINDINGS RESOLVED' if ok else 'ISSUES REMAIN')
PYEOF

